package com.highpass.runspot.chat.dto;import com.highpass.runspot.chat.domain.*;import java.time.LocalDateTime;import java.util.List;public record ChatSendResponse(Long messageId,String clientMessageId,Long roomId,Long senderId,String senderName,boolean host,ChatMessageType messageType,String content,List<String> imageKeys,LocalDateTime createdAt){public static ChatSendResponse from(ChatMessage m,boolean host){return new ChatSendResponse(m.getId(),m.getClientMessageId(),m.getRoom().getId(),m.getSender().getId(),m.getSender().getName(),host,m.getMessageType(),m.getContent(),m.getImageKeys(),m.getCreatedAt());}}
